EbmlElement* findNextEbmlElement(IOCallback& dataStream, const EbmlSemanticContext& context, int& upperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    if (!dataStream.isValid() || MaxDataSize == 0) {
        return nullptr;
    }

    uint64 bytesRead = 0;
    uint64 remainingSize = MaxDataSize;
    uint8 idBuffer[8];
    uint64 idLength = 0;

    // Read potential ID
    while (bytesRead < MaxDataSize) {
        if (dataStream.read(idBuffer + idLength, 1) != 1) {
            return nullptr;
        }
        bytesRead++;
        idLength++;
        if ((idBuffer[0] & 0x80) != 0x80) {
            break;
        }
        if (idLength > 8) {
            return nullptr; // EBML IDs cannot be longer than 8 bytes
        }
    }

    if (idLength == 0) {
        return nullptr; // No valid ID found
    }

    uint64 elementSize = 0;
    uint64 sizeLength = 0;

    // Read potential size
    while (sizeLength < 8 && bytesRead < MaxDataSize) {
        if (dataStream.read(reinterpret_cast<uint8*>(&elementSize) + sizeLength, 1) != 1) {
            return nullptr;
        }
        bytesRead++;
        sizeLength++;
        if ((reinterpret_cast<uint8*>(&elementSize)[sizeLength] & 0x80) == 0x80) {
            break;
        }
    }

    if (sizeLength == 0) {
        return nullptr; // No valid size found
    }

    // Validate size
    if (elementSize > (MaxDataSize - bytesRead)) {
        return nullptr; // Element size exceeds remaining data
    }

    // Create EBML element
    EbmlElement* element = context.createElement(idBuffer, idLength, elementSize);
    if (!element) {
        return nullptr;
    }

    // Set element properties
    element->setUpperLevel(upperLevel);
    if (AllowDummyElt || (idBuffer[0] & 0x40) != 0x40) {
        element->setDummy(false);
    } else {
        element->setDummy(true);
    }

    if (MaxLowerLevel > 0) {
        element->setMaxLowerLevel(MaxLowerLevel);
    }

    return element;
}
